-- All statements run inside the selected schema in one PostgreSQL transaction.
CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS core_owners(id text PRIMARY KEY, revision bigint NOT NULL DEFAULT 0, settings jsonb NOT NULL DEFAULT '{"auto_save_low_sensitivity":true}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS core_subjects(owner text NOT NULL REFERENCES core_owners(id), id text NOT NULL, label text NOT NULL, consent text NOT NULL DEFAULT 'granted', PRIMARY KEY(owner,id));
CREATE TABLE IF NOT EXISTS core_versions(owner text NOT NULL REFERENCES core_owners(id), dependency text NOT NULL, revision bigint NOT NULL DEFAULT 0, PRIMARY KEY(owner,dependency));
CREATE TABLE IF NOT EXISTS core_entities(owner text NOT NULL REFERENCES core_owners(id), kind text NOT NULL, id text NOT NULL, subject text NOT NULL, case_id text, revision bigint NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active', data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,kind,id), FOREIGN KEY(owner,subject) REFERENCES core_subjects(owner,id));
CREATE INDEX IF NOT EXISTS core_entity_scope ON core_entities(owner,kind,subject,case_id,status,created_at);
CREATE TABLE IF NOT EXISTS core_operations(owner text NOT NULL REFERENCES core_owners(id), operation_id text NOT NULL, fingerprint text NOT NULL, kind text NOT NULL, result_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,operation_id));
CREATE TABLE IF NOT EXISTS core_channels(channel text NOT NULL, external_id text NOT NULL, binding_kind text NOT NULL DEFAULT 'user', owner text NOT NULL, subject text NOT NULL, PRIMARY KEY(channel,external_id), FOREIGN KEY(owner,subject) REFERENCES core_subjects(owner,id));
CREATE TABLE IF NOT EXISTS core_revocations(owner text NOT NULL REFERENCES core_owners(id), kind text NOT NULL, entity_id text NOT NULL, operation text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', revision bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,kind,entity_id));
CREATE TABLE IF NOT EXISTS core_legacy_map(owner text NOT NULL REFERENCES core_owners(id), source text NOT NULL, legacy_id text NOT NULL, kind text NOT NULL, result_id text, status text NOT NULL, PRIMARY KEY(owner,source,legacy_id,kind));
CREATE TABLE IF NOT EXISTS core_runs(id text PRIMARY KEY, owner text NOT NULL, subject text NOT NULL, operation_id text NOT NULL, fingerprint text NOT NULL, request jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', result jsonb, attempts integer NOT NULL DEFAULT 0, calls integer NOT NULL DEFAULT 0, call_limit integer NOT NULL, repair_used boolean NOT NULL DEFAULT false, state_version jsonb NOT NULL DEFAULT '{}', checkpoint jsonb NOT NULL DEFAULT '{}', lease_token text, lease_until timestamptz, error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner,operation_id), FOREIGN KEY(owner,subject) REFERENCES core_subjects(owner,id), CHECK(calls>=0 AND calls<=call_limit));
CREATE INDEX IF NOT EXISTS core_run_queue ON core_runs(status,lease_until,created_at);
CREATE TABLE IF NOT EXISTS core_model_charges(owner text NOT NULL, run_id text NOT NULL REFERENCES core_runs(id), operation_id text NOT NULL, repair boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner,run_id,operation_id));
CREATE TABLE IF NOT EXISTS tarot_draws(id text PRIMARY KEY, owner text NOT NULL, subject text NOT NULL, case_id text NOT NULL, stage text NOT NULL, payload jsonb NOT NULL, private_deck jsonb NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS tarot_draw_scope ON tarot_draws(owner,subject,case_id,stage,created_at);
CREATE TABLE IF NOT EXISTS tarot_requests(owner text, operation text, request_key text, fingerprint text, result_id text, result_type text, deleted boolean DEFAULT false, PRIMARY KEY(owner,operation,request_key));
CREATE TABLE IF NOT EXISTS tarot_readings(id text PRIMARY KEY, owner text, draw_id text REFERENCES tarot_draws(id) ON DELETE CASCADE, version integer, payload jsonb, UNIQUE(draw_id,version));
CREATE TABLE IF NOT EXISTS delivery_outbox(id text PRIMARY KEY, owner text, subject text, business_id text, channel text, target text, run_id text, payload jsonb, dependencies jsonb, status text DEFAULT 'pending', attempts integer DEFAULT 0, claim_token text, lease_until timestamptz, due timestamptz, receipt text DEFAULT '', error text DEFAULT '', reconciliation jsonb DEFAULT '{}', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), UNIQUE(owner,business_id,channel,target));
